/* Design system generated by Taster. Load after registry/src/tokens.css; components read the alias tokens only. */
/* density airy, contrast standard, roundness pillow, type-expression poster, color-restraint achromatic, elevation raised, motion still, stroke light; dark scheme */
:root {
  --accent-fg: #ffffff;
  --success: #5bbd74;
  --danger: #fd7468;
  --destructive: #fd7468;
  --delta-up: #5bbd74;
  --delta-down: #fd7468;
  --sp-1: 4px;
  --sp-2: 10px;
  --sp-3: 14px;
  --sp-4: 18px;
  --sp-5: 22px;
  --sp-6: 28px;
  --sp-8: 36px;
  --sp-12: 54px;
  --sp-16: 72px;
  --control-sm: 34px;
  --control-md: 38px;
  --lh-normal: 1.55;
  --lh-snug: 1.325;
  --muted-foreground: oklch(0.708 0 0);
  --text-subtle: oklch(0.65 0 0);
  --muted: oklch(0.269 0 0);
  --secondary: oklch(0.269 0 0);
  --radius: 1.25rem;
  --r-sm: 12px;
  --r-md: 16px;
  --r-card: 20px;
  --r-xl: 28px;
  --r-2xl: 36px;
  --r-3xl: 44px;
  --r-4xl: 52px;
  --font: 'IBM Plex Sans', 'IBM Plex Sans KR', -apple-system, system-ui, sans-serif;
  --t-display: 60px;
  --t-h1: 44px;
  --t-h2: 32px;
  --t-title: 18px;
  --lh-tight: 1;
  --w-semi: 700;
  --brand: #4c1d95;
  --highlight: oklch(0.7 0 0);
  --accent-soft: oklch(0.38 0.178 293.745 / 12%);
  --chart-1: oklch(0.98 0 0);
  --chart-2: oklch(0.82 0 0);
  --chart-3: oklch(0.66 0 0);
  --chart-4: oklch(0.5 0 0);
  --chart-5: oklch(0.38 0 0);
  --chart-6: oklch(0.28 0 0);
  --success-soft: oklch(0.721 0.141 149.912 / 12%);
  --warning-soft: oklch(0.72 0.14 38 / 12%);
  --danger-soft: oklch(0.72 0.17 27.166 / 12%);
  --sh-card: 0 1px 3px rgba(0,0,0,.35), 0 2px 6px rgba(0,0,0,.25);
  --sh-pop: 0 10px 30px rgba(0,0,0,.4);
  --card: oklch(1 0 0 / 4%);
  --popover: oklch(0.2 0 0);
  --scrim: oklch(0 0 0 / 60%);
  --dur-press: 100ms;
  --dur-tooltip: 100ms;
  --dur-dropdown: 120ms;
  --dur-modal: 150ms;
  --stagger-step: 0ms;
  --press-scale: 1;
  --enter-scale: 1;
  --enter-offset: 0px;
  --blur-mask: 0px;
  --border: oklch(1 0 0 / 12%);
  --border-soft: rgba(255, 255, 255, 0.09);
  --input: oklch(1 0 0 / 20%);
  --icon-stroke: 2;
}
@media (prefers-reduced-motion: reduce) {
  :root {
    --dur-press: 1ms;
    --dur-tooltip: 1ms;
    --dur-dropdown: 1ms;
    --dur-modal: 1ms;
    --stagger-step: 0ms;
    --press-scale: 1;
    --enter-scale: 1;
    --enter-offset: 0px;
    --blur-mask: 0px;
  }
}
@media (prefers-reduced-transparency: reduce) {
  :root {
    --bg-elev: var(--bg-sunken);
    --scrim: oklch(0 0 0 / 80%);
  }
}
